{"path":"/tmp/do.py","content":"import os, json, hashlib, shutil, sys

OLD = '/work/shares/old-nas'
TEAM = '/work/shares/team'
P = json.load(open('/tmp/plan.json'))
mapping = P['mapping']
mapping[OLD] = TEAM
old_links = list(P['links'])

def sha(p):
    h = hashlib.sha256()
    with open(p, 'rb') as f:
        for c in iter(lambda: f.read(1 << 20), b''):
            h.update(c)
    return h.hexdigest()

def newpath(op):
    if op in mapping:
        return mapping[op]
    return os.path.join(newpath(os.path.dirname(op)), os.path.basename(op))

# ---- before snapshot of team (files + links) and old-nas links resolution
def snapshot(root):
    snap = {}
    for r, ds, fs in os.walk(root):
        for n in ds + fs:
            p = os.path.join(r, n)
            st = os.lstat(p)
            if os.path.islink(p):
                snap[p] = ('L', os.readlink(p), st.st_mtime_ns)
            elif os.path.isfile(p):
                snap[p] = ('F', sha(p), st.st_mtime_ns)
            else:
                snap[p] = ('D', None, None)
    return snap

team_before = snapshot(TEAM)
old_before = snapshot(OLD)
link_content_before = {}
for lp in old_links + [p for p, v in team_before.items() if v[0] == 'L']:
    try:
        link_content_before[lp] = sha(lp)
    except Exception as e:
        link_content_before[lp] = 'ERR ' + str(e)
json.dump({'team': team_before, 'old': old_before, 'lc': link_content_before},
          open('/tmp/before.json', 'w'))
print('snapshot done', len(team_before), len(old_before))

# ---- 1. create directories
for op, tp in mapping.items():
    if op != OLD and os.path.isdir(op) and not os.path.lexists(tp):
        os.makedirs(tp)
        print('mkdir', tp)

# ---- 2. move files / drop duplicates
for op, tp in sorted(mapping.items()):
    if op == OLD or os.path.isdir(op) and not os.path.islink(op):
        continue
    if not os.path.lexists(op):
        continue
    if os.path.lexists(tp):
        if os.path.isfile(tp) and not os.path.islink(tp) and sha(tp) == sha(op):
            os.remove(op)
            continue
        raise SystemExit('unexpected existing target ' + tp)
    os.rename(op, tp)

# ---- 3. recreate links (old-nas links -> team, with retargeting)
def new_target(lp, t):
    absolute_old = os.path.normpath(os.path.join(os.path.dirname(lp), t))
    if absolute_old == OLD or absolute_old.startswith(OLD + '/'):
        nt = newpath(absolute_old)
        if os.path.isabs(t):
            return nt
        return os.path.relpath(nt, os.path.dirname(newpath(lp)))
    return t

for lp in old_links:
    t = os.readlink(lp)
    mt = os.lstat(lp).st_mtime_ns
    nl = newpath(lp)
    nt = new_target(lp, t)
    if os.path.lexists(nl):
        raise SystemExit('link target name taken ' + nl)
    os.symlink(nt, nl)
    os.utime(nl, ns=(mt, mt), follow_symlinks=False)
    os.remove(lp)
    print('link', nl, '->', nt)

# team links pointing into old-nas (retarget in place)
for r, ds, fs in os.walk(TEAM):
    for n in fs + ds:
        p = os.path.join(r, n)
        if os.path.islink(p):
            t = os.readlink(p)
            full = os.path.normpath(os.path.join(r, t))
            if full == OLD or full.startswith(OLD + '/'):
                mt = os.lstat(p).st_mtime_ns
                nt = new_target(p, t)
                os.remove(p)
                os.symlink(nt, p)
                os.utime(p, ns=(mt, mt), follow_symlinks=False)
                print('retarget', p, '->', nt)

# ---- 4. remove old-nas (must now only hold empty dirs)
left = []
for r, ds, fs in os.walk(OLD):
    left += [os.path.join(r, f) for f in fs]
print('files left in old-nas:', left)
if not left:
    shutil.rmtree(OLD)
    print('removed old-nas')
